function minInsertions(s) {
  const stack = [];
  let insertions = 0;
  let i = 0;

  while (i < s.length) {
    if (s[i] === '(') {
      stack.push('(');
      i++;
    } else {
      if (s[i + 1] === ')') {
        i += 2;
      } else {
        insertions++;
        i++;
      }
      if (stack.length > 0) {
        stack.pop();
      } else {
        insertions++;
      }
    }
  }
  return insertions + 2 * stack.length;
}

