function minInsertions(s) {
  // 0-1 BFS over (position, unmatched opens, half of a '))' seen); inserting a character costs 1.
  const n = s.length, cap = n + 2;
  const best = new Map();
  const key = (p, o, h) => (p * (cap + 1) + o) * 2 + h;
  const deque = [[0, 0, 0, 0]];
  while (deque.length) {
    const [p, o, h, d] = deque.shift();
    const id = key(p, o, h);
    if (best.has(id) && best.get(id) <= d) continue;
    best.set(id, d);
    if (p === n && o === 0 && h === 0) return d;
    const moves = [];
    if (h === 1) {
      if (p < n && s[p] === ')') moves.push([p + 1, o, 0, 0]);
      moves.push([p, o, 0, 1]);
    } else {
      if (p < n && s[p] === '(' && o < cap) moves.push([p + 1, o + 1, 0, 0]);
      if (p < n && s[p] === ')' && o > 0) moves.push([p + 1, o - 1, 1, 0]);
      if (o < cap) moves.push([p, o + 1, 0, 1]);
      if (o > 0) moves.push([p, o - 1, 1, 1]);
    }
    for (const [np, no, nh, cost] of moves) {
      if (cost === 0) deque.unshift([np, no, nh, d]);
      else deque.push([np, no, nh, d + 1]);
    }
  }
  return -1;
}

