function generate(rand, size) {
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 10);
  const openChance = 0.2 + rand() * 0.6;
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < openChance ? '(' : ')';
  return [s];
}
